                    if curr_end > b_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result_sorted = sorted(result)
    final = []
    for start, end in result_sorted:
        if final and start <= final[-1][1]:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

